import openpyxl, datetime, random
from openpyxl.styles import Font, PatternFill, Alignment
random.seed(7)

def luhn_id(prefix9):
    # يولّد رقم هوية 10 خانات يجتاز فحص الخانة الأخيرة (وهمي)
    for d in range(10):
        s = prefix9 + str(d); tot = 0
        for i,ch in enumerate(s):
            n=int(ch)
            if i%2==0:
                n*=2
                if n>9: n-=9
            tot+=n
        if tot%10==0: return s
def iban_sa(bank2, acct18):
    # آيبان سعودي وهمي بخانة تحقق صحيحة
    bban = bank2 + acct18
    rearr = bban + "SA00"
    num = "".join(str(ord(c)-55) if c.isalpha() else c for c in rearr)
    chk = 98 - int(num) % 97
    return f"SA{chk:02d}{bban}"

